'use client';

import React, { useState, useEffect } from 'react';
import { formatINR } from '@/lib/utils/currency';

interface Transaction {
  id: string;
  party: string;
  type: 'Hospital Bulk Supply' | 'Direct Prescription Flow';
  amount: number;
  date: string;
  status: string;
}

interface DashboardViewProps {
  revenue: number;
  patientSales: number;
  hospitalSales: number;
  ordersCount: number;
}

export default function DashboardView({ revenue, patientSales, hospitalSales, ordersCount }: DashboardViewProps) {
  const [filterStatus, setFilterStatus] = useState<string>('ALL');
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  // Interactive Form UI States
  const [showForm, setShowForm] = useState<boolean>(false);
  const [formParty, setFormParty] = useState<string>('');
  const [formType, setFormType] = useState<'Hospital Bulk Supply' | 'Direct Prescription Flow'>('Direct Prescription Flow');
  const [formAmount, setFormAmount] = useState<string>('');
  
  // ΓöÇΓöÇΓöÇ AUTOMATED RECORD COUNTER STATE FOR SEQUENTIAL TOKEN GENERATION ΓöÇΓöÇΓöÇ
  const [nextIdSequence, setNextIdSequence] = useState<number>(1);

  // Hydrate vendor logs safely from local memory cache
  useEffect(() => {
    const savedTx = localStorage.getItem('curasync_manual_ledger');
    if (savedTx) {
      const parsed = JSON.parse(savedTx);
      setTransactions(parsed);
      // Calculate next index sequence offset defensively to avoid ID collisions
      setNextIdSequence(parsed.length + 1);
    } else {
      const baseContracts: Transaction[] = [
        { id: "RX-ORD-9021", party: "Aishwarya D S", type: "Direct Prescription Flow", amount: 700, date: "Today, 10:30 AM", status: "Pending Verification" },
        { id: "RX-ORD-8842", party: "Nikhil Kumar", type: "Direct Prescription Flow", amount: 60, date: "Yesterday", status: "Out for Delivery" },
        { id: "PO-2026-00412", party: "Victoria Hospital, Bengaluru", type: "Hospital Bulk Supply", amount: 35500, date: "July 04, 2026", status: "Received" }
      ];
      setTransactions(baseContracts);
      setNextIdSequence(baseContracts.length + 1);
      localStorage.setItem('curasync_manual_ledger', JSON.stringify(baseContracts));
    }
  }, []);

  // ΓöÇΓöÇΓöÇ COMMIT FORM ACTION CAPTURING AN AUTOGENERATED STRING TOKEN ID ΓöÇΓöÇΓöÇ
  const handleAddTransaction = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formParty.trim() || !formAmount.trim()) return;

    // Generates a clean auto-padded reference matching current calendar year metric configurations
    const currentYear = new Date().getFullYear();
    const autoGeneratedTokenId = `TX-${currentYear}-${String(nextIdSequence).padStart(4, '0')}`;

    const newEntry: Transaction = {
      id: autoGeneratedTokenId,
      party: formParty.trim(),
      type: formType,
      amount: parseFloat(formAmount) || 0,
      date: new Date().toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }),
      status: formType === 'Hospital Bulk Supply' ? 'Received' : 'Pending Verification'
    };

    const updatedList = [newEntry, ...transactions];
    setTransactions(updatedList);
    setNextIdSequence(prev => prev + 1); // Bump counter sequence for the next insertion
    localStorage.setItem('curasync_manual_ledger', JSON.stringify(updatedList));

    // Reset parameters
    setFormParty('');
    setFormAmount('');
    setShowForm(false);
  };

  const dynamicPatientSales = transactions.filter(t => t.type === 'Direct Prescription Flow').reduce((sum, t) => sum + t.amount, 0);
  const dynamicHospitalSales = transactions.filter(t => t.type === 'Hospital Bulk Supply').reduce((sum, t) => sum + t.amount, 0);
  const dynamicGrossRevenue = dynamicPatientSales + dynamicHospitalSales;

  const filteredTransactions = transactions.filter(tx => {
    const matchesStatus = filterStatus === 'ALL' || tx.type === filterStatus;
    const matchesSearch = tx.party.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          tx.id.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesStatus && matchesSearch;
  });

  return (
    <div className="space-y-6 animate-fadeIn">
      
      {/* METRIC ANALYSIS CARDS */}
      <div className="bg-[#EBF1F1] border border-[#CBD6D6] rounded-2xl p-5 shadow-2xs space-y-4">
        <div className="flex justify-between items-center">
          <span className="text-[10px] font-mono font-black uppercase tracking-wider text-[#4A5D5E] block">Live Financial Balances</span>
          <button 
            onClick={() => setShowForm(!showForm)} 
            className="bg-[#4A5D5E] text-white font-black text-xs px-4 py-2 rounded-xl shadow-xs transition-all hover:bg-[#3b494a] cursor-pointer"
          >
            {showForm ? 'Γ£ò Close Form' : '∩╝ï Log Manual Transaction'}
          </button>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <div className="bg-white border border-[#CBD6D6] p-5 rounded-xl">
            <span className="text-[10px] font-black text-slate-800 uppercase tracking-wide block">Gross Revenue Balance</span>
            <strong className="text-2xl font-black text-[#4A5D5E] mt-1 block font-mono">Γé╣{dynamicGrossRevenue.toLocaleString('en-IN')}</strong>
            <span className="text-[10px] text-emerald-600 font-bold block mt-1">Γåæ Dynamic Active Total</span>
          </div>

          <div className="bg-white border border-[#CBD6D6] p-5 rounded-xl">
            <span className="text-[10px] font-black text-slate-800 uppercase tracking-wide block">Hospital Bulk Supply</span>
            <strong className="text-2xl font-black text-slate-950 mt-1 block font-mono">Γé╣{dynamicHospitalSales.toLocaleString('en-IN')}</strong>
            <span className="text-[10px] text-blue-600 font-bold block mt-1">B2B Segments Ledger</span>
          </div>

          <div className="bg-white border border-[#CBD6D6] p-5 rounded-xl">
            <span className="text-[10px] font-black text-slate-800 uppercase tracking-wide block">Direct Prescription Flow</span>
            <strong className="text-2xl font-black text-slate-950 mt-1 block font-mono">Γé╣{dynamicPatientSales.toLocaleString('en-IN')}</strong>
            <span className="text-[10px] text-amber-600 font-bold block mt-1">B2C Retail Entry Outflow</span>
          </div>

          <div className="bg-white border border-[#CBD6D6] p-5 rounded-xl">
            <span className="text-[10px] font-black text-slate-800 uppercase tracking-wide block">Transactions Tracked</span>
            <strong className="text-2xl font-black text-slate-950 mt-1 block font-mono">{transactions.length} Records</strong>
            <span className="text-[10px] text-slate-800 font-bold block mt-1">Total Entries in Memory</span>
          </div>
        </div>
      </div>

      {/* ΓöÇΓöÇΓöÇ DYNAMIC FORM WITH AN AUTOGENERATED STATIC VALUE PREVIEW ΓöÇΓöÇΓöÇ */}
      {showForm && (
        <form onSubmit={handleAddTransaction} className="bg-white border-2 border-[#4A5D5E] rounded-2xl p-5 shadow-md space-y-4 animate-fadeIn text-xs font-bold text-slate-900">
          <h4 className="text-sm font-black text-slate-900 border-b pb-1.5">Record New Transaction Event</h4>
          
          <div className="grid grid-cols-1 sm:grid-cols-4 gap-4">
            
            {/* ≡ƒñû AUTOMATIC ID VIEWPORT CONTAINER */}
            <div className="flex flex-col gap-1">
              <label className="text-slate-800">Reference Token ID (Auto-Generated)</label>
              <div className="border border-slate-200 bg-slate-50 text-[#4A5D5E] font-mono font-bold rounded-xl p-3 select-none tracking-wide text-[13px]">
                {`TX-${new Date().getFullYear()}-${String(nextIdSequence).padStart(4, '0')}`}
              </div>
            </div>

            <div className="flex flex-col gap-1">
              <label>Client / Entity Party</label>
              <input type="text" required placeholder="Enter name..." value={formParty} onChange={e => setFormParty(e.target.value)} className="border border-slate-200 rounded-xl p-2.5 text-black font-semibold focus:outline-none focus:border-[#4A5D5E]" />
            </div>

            <div className="flex flex-col gap-1">
              <label>Channel Pipeline Type</label>
              <select value={formType} onChange={e => setFormType(e.target.value as any)} className="border border-slate-200 rounded-xl p-2.5 bg-white cursor-pointer text-black font-semibold focus:outline-none focus:border-[#4A5D5E]">
                <option value="Direct Prescription Flow">Direct Prescription (B2C)</option>
                <option value="Hospital Bulk Supply">Hospital Bulk PO (B2B)</option>
              </select>
            </div>

            <div className="flex flex-col gap-1">
              <label>Net Value Amount (Γé╣)</label>
              <input type="number" required placeholder="Amount in Γé╣" value={formAmount} onChange={e => setFormAmount(e.target.value)} className="border border-slate-200 rounded-xl p-2.5 text-black font-semibold focus:outline-none focus:border-[#4A5D5E]" />
            </div>

          </div>

          <div className="flex justify-end pt-2">
            <button type="submit" className="bg-emerald-600 text-white font-black px-6 py-2.5 rounded-xl shadow-xs hover:bg-emerald-700 transition-all cursor-pointer">
              Γ£ô Commit Transaction to Ledger
            </button>
          </div>
        </form>
      )}

      {/* AUDIT DATA TABLES */}
      <div className="bg-white border border-[#CBD6D6] rounded-2xl p-6 shadow-xs space-y-4">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 border-b-2 border-slate-200 pb-4">
          <div>
            <h4 className="text-base font-black text-slate-900">Audit Trail Pipeline</h4>
            <p className="text-xs font-semibold text-slate-800 mt-0.5">Live records populated interactively by the vendor network system logs.</p>
          </div>
          
          <div className="flex items-center gap-2">
            <input 
              type="text" 
              placeholder="Search party/ID..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="border border-slate-200 rounded-xl px-3 py-1.5 text-xs font-semibold focus:outline-none focus:border-[#4A5D5E] bg-[#F4F7F6]"
            />
            <select 
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value)}
              className="border border-slate-200 rounded-xl px-3 py-1.5 text-xs font-bold bg-white text-slate-900 focus:outline-none cursor-pointer"
            >
              <option value="ALL">All Channels</option>
              <option value="Hospital Bulk Supply">B2B Institutional</option>
              <option value="Direct Prescription Flow">B2C Prescription</option>
            </select>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse text-xs">
            <thead>
              <tr className="bg-[#F4F7F6] border-b-2 border-slate-200 text-slate-800 font-black uppercase tracking-wider">
                <th className="py-3 px-4">Transaction ID</th>
                <th className="py-3 px-4">Associated Client Party</th>
                <th className="py-3 px-4">Taxonomy Channel</th>
                <th className="py-3 px-4">Timestamp Log</th>
                <th className="py-3 px-4 text-right">Net Value</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 font-medium text-slate-900">
              {filteredTransactions.map((tx, idx) => (
                <tr key={idx} className="hover:bg-slate-100/60 transition-all">
                  <td className="py-3.5 px-4 font-mono font-bold text-slate-900">{tx.id}</td>
                  <td className="py-3.5 px-4 font-black text-slate-900">{tx.party}</td>
                  <td className="py-3.5 px-4">
                    <span className={`px-2.5 py-0.5 rounded text-[10px] font-black ${
                      tx.type === 'Hospital Bulk Supply' 
                        ? 'bg-blue-50 text-blue-700 border border-blue-200' 
                        : 'bg-amber-50 text-amber-700 border border-amber-200'
                    }`}>
                      {tx.type}
                    </span>
                  </td>
                  <td className="py-3.5 px-4 text-slate-950 font-bold">{tx.date}</td>
                  <td className="py-3.5 px-4 text-right font-mono font-black text-slate-900">
                    {formatINR(tx.amount)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

    </div>
  );
}
